pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address other) public {
        // Restrict amounts to avoid overflow in balance tracking
        vm.assume(depositAmount > 0 && depositAmount <= type(uint128).max);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);

        // Restrict actor to non-zero, non-system address
        address actor = address(uint160(other) | 1);
        vm.assume(actor != address(this) && actor != address(0));

        // Initialize the contract and set MinSum so collections are allowed
        c.SetMinSum(0);
        vm.prank(actor);
        c.Initialized();

        // Set up actor with ether and deposit
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // Record balance before collecting
        uint256 balanceBefore = c.balances(actor);

        // Collect
        vm.prank(actor);
        c.Collect(collectAmount);

        // Retrieve balance after collecting
        uint256 balanceAfter = c.balances(actor);

        // Invariant: If a user deposits and then collects an amount <= their balance,
        // the final balance must equal balanceBefore - collectAmount.
        assertTrue(balanceAfter == balanceBefore - collectAmount);
    }
}

