contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amt1, uint256 amt2, uint256 collectAmt, address user) public {
        // Bound to avoid overflow and ensure feasible amounts
        bound(amt1, 1, 1e24);
        bound(amt2, 0, 1e24);
        bound(collectAmt, 0, 1e24);
        vm.assume(user != address(0) && user != address(this));

        // Initialize the contract with a minimum sum
        c.SetMinSum(0);
        c.SetLogFile(address(this));
        c.Initialized();

        // Deposit amt1 for user
        vm.deal(user, amt1);
        vm.prank(user);
        c.Deposit{value: amt1}();

        // Deposit amt2 for this contract (or another), to create more state
        vm.deal(address(this), amt2);
        c.Deposit{value: amt2}();

        // User collects collectAmt (may revert if insufficient or below MinSum)
        vm.prank(user);
        try c.Collect(collectAmt) {} catch {}

        // The invariant: sum of all balances equals total Ether received minus Ether sent out
        uint256 totalDeposited = amt1 + amt2;
        // We need to compute total collected: the only external call sending Ether is Collect to user
        // The amount sent is collectAmt if the call succeeded; otherwise 0.
        // Because Collect can revert, we approximate by tracking the user's balance + this contract's balance + address(c).balance
        uint256 sumBalances = c.balances(user) + c.balances(address(this));
        assertTrue(sumBalances == address(c).balance);
    }
}

