        try c.Collect(collectAmount) {
            // If collect succeeds, assert balance decreased by exactly collectAmount
            uint256 balanceAfter = c.balances(caller);
            assertEq(balanceAfter, balanceBefore - collectAmount);
        } catch {
            // If collect reverts, we don't assert on balance change; property holds vacuously
            // Since we only assert on successful Collect, the property is: success => balance diff = collectAmount
        }
    }
