contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 amount, address sender) public {
        // Bound amount to a value that can cause overflow
        amount = uint96(bound(amount, 1, type(uint96).max));
        // sender must not be address(0)
        vm.assume(sender != address(0));

        uint256 preBalance = c.balances(sender);

        // Give sender enough ether to make the deposit
        vm.deal(sender, amount);
        vm.prank(sender);

        bool ok = true;
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 postBalance = c.balances(sender);

        // If the deposit succeeded, the balance must have increased
        // In the correct contract, if overflow would occur, Deposit reverts
        // In the buggy contract, overflow wraps around, causing balance to not increase
        assertTrue(!ok || postBalance > preBalance);
    }
}

